SELECT sys_id AS revision_id, request_fingerprint, processing_status,
       response_json::text AS response_json
FROM client_order_revision
WHERE sys_plant_cd = #{sysPlantCd}
  AND client_request_id = #{clientRequestId}

SELECT order_status FROM order_master
WHERE sys_id = #{orderMasterId} AND link_sys_id = #{tableSysId}
  AND sys_plant_cd = #{sysPlantCd}
FOR UPDATE

SELECT od.sys_id
FROM order_detail od
INNER JOIN order_group og ON og.sys_id = od.link_sys_id3 AND og.sys_plant_cd = od.sys_plant_cd
WHERE od.sys_plant_cd = #{sysPlantCd}
  AND og.link_sys_id = #{orderMasterId}
  AND og.sys_id IN
#{id}
  AND od.sys_id IN
#{id}
  AND NOT EXISTS (
      SELECT 1 FROM client_order_revision_removed_detail removed
      WHERE removed.order_detail_sys_id = od.sys_id
  )
ORDER BY od.sys_id
FOR UPDATE OF od

mapper.update:
UPDATE order_group SET
    order_status = '99!', cancel_type = 'ORDER_REVISION', cancel_yn = 'Y',
    cancel_reason = '주문 수정으로 모든 메뉴 제거', cancel_description = '',
    cancel_datetime = #{cancelledAt}, modify_user_id = #{userId}, modify_datetime = #{cancelledAt}
WHERE sys_plant_cd = #{sysPlantCd}
  AND order_status IN ('01', '02')
  AND sys_id IN
#{id}

UPDATE client_order_revision SET processing_status = 'COMPLETED',
    response_json = CAST(#{responseJson} AS jsonb), complete_datetime = #{completedAt}
WHERE sys_id = #{revisionId} AND processing_status = 'PROCESSING'
